          <input type="text" id="titleInput" placeholder="Enter file title" aria-label="File title" />
          <textarea id="descriptionInput" placeholder="Enter file description" aria-label="File description"></textarea>
          <button id="uploadBtn">Upload File</button>
          <div id="uploadMessage"></div>
        </div>

        <div class="file-list">
          <h2>Uploaded Files</h2>
          <div id="filesList"></div>
        </div>

        <script>
          let uploadedFiles = [];

          document.getElementById('uploadBtn').addEventListener('click', function() {
            const fileInput = document.getElementById('fileInput');
            const titleInput = document.getElementById('titleInput');
            const descriptionInput = document.getElementById('descriptionInput');
            const messageDiv = document.getElementById('uploadMessage');

            messageDiv.innerHTML = '';
            messageDiv.className = '';

            if (!fileInput.files.length) {
              messageDiv.innerHTML = 'Please select a file';
              messageDiv.className = 'error';
              return;
            }

            if (!titleInput.value.trim()) {
              messageDiv.innerHTML = 'Please enter a title';
              messageDiv.className = 'error';
              return;
            }

            if (!descriptionInput.value.trim()) {
              messageDiv.innerHTML = 'Please enter a description';
              messageDiv.className = 'error';
              return;
            }

            const file = fileInput.files[0];
            const fileData = {
              name: file.name,
              title: titleInput.value.trim(),
              description: descriptionInput.value.trim(),
              size: file.size,
              uploadedAt: new Date().toLocaleString()
            };

            uploadedFiles.push(fileData);
            messageDiv.innerHTML = 'File uploaded successfully!';
            messageDiv.className = 'success';

            // Reset form
            fileInput.value = '';
            titleInput.value = '';
            descriptionInput.value = '';

            renderFilesList();
          });

          function renderFilesList() {
            const filesList = document.getElementById('filesList');
            if (uploadedFiles.length === 0) {
              filesList.innerHTML = '<p>No files uploaded yet</p>';
              return;
            }

            filesList.innerHTML = uploadedFiles.map((file, index) => `
              <div class="file-item">
                <h3>${file.title}</h3>
                <p><strong>File:</strong> ${file.name}</p>
                <p><strong>Description:</strong> ${file.description}</p>
                <p><strong>Size:</strong> ${file.size} bytes</p>
                <p><strong>Uploaded:</strong> ${file.uploadedAt}</p>
                <button onclick="deleteFile(${index})">Delete</button>
              </div>
            `).join('');
          }

          window.deleteFile = function(index) {
            uploadedFiles.splice(index, 1);
            renderFilesList();
          };

          renderFilesList();
        </script>
      </body>
      </html>
    `);
  });

